class Solution {
  public int[] lexSmallestNegatedPerm(int n, long target) {
    long total = (long) n * (n + 1) / 2;
    long diff = total - target;
    if (diff < 0 || diff % 2 != 0 || diff / 2 > total) return new int[0];
    long remaining = diff / 2;
    boolean[] negate = new boolean[n + 1];
    for (int v = n; v >= 1 && remaining > 0; v--) {
      long lower = (long) (v - 1) * v / 2;
      if (remaining >= v && remaining - v <= lower) {
        negate[v] = true;
        remaining -= v;
      }
    }
    if (remaining != 0) return new int[0];
    int[] res = new int[n];
    int p = 0;
    for (int v = n; v >= 1; v--) if (negate[v]) res[p++] = -v;
    for (int v = 1; v <= n; v++) if (!negate[v]) res[p++] = v;
    return res;
  }
}
